import { createVocabularyLesson } from '../../../schemas/index.js';

const level = 'A1';
const status = 'ready';
function q(question, options, answer, explanation = '', context = '') { return { question, options, answer, explanation, context }; }
function word(word, meaning, example = '', note = '') { return { word, meaning, example, note }; }
function chunk(chunk, translation, why = '', warning = '') { return { chunk, translation, why, warning }; }
function ex(text, translation, why = '', warning = '') { return { text, translation, why, warning }; }
function dialogue(title, lines, focus = '') { return { title, lines, focus }; }
function task(instruction, note = '', expected = '') { return { instruction, note, expected }; }

function makeVocabLesson(input) {
  return createVocabularyLesson({
    level,
    status,
    estimatedMinutes: 55,
    ...input,
    masteryCriteria: { minPracticeAccuracy: 80, requiredProduction: 2, tags: ['a1-vocabulary', input.id, 'deep-approved-target'] },
  });
}

